// Yoroxy LowBand — 単一ファイル版 (Ultraviolet + Bare + 低速回線キャッシュ)
// このファイル1つだけで動きます。必要な外部パッケージは @tomphttp/bare-server-node のみ。
const http = require('http');
const zlib = require('zlib');
const { createBareServer } = require('@tomphttp/bare-server-node');
const PORT = process.env.PORT || 8080;
const MIME = { html:'text/html; charset=utf-8', js:'text/javascript; charset=utf-8', css:'text/css; charset=utf-8', json:'application/json' };
const ASSETS = {"/app.js":"","/frame.css":"","/frame.html":"","/frame.js":"","/index.html":"","/lowband.css":"","/style.css":"","/sw.js":"","/uv/uv.bundle.js":"","/uv/uv.client.js":"","/uv/uv.config.js":"H4sIAAAAAAACA4WPQQqDMBBF955iFgVBSrK39BiuJcbRpgxJmZgolN69xFjirqvw/3vDTGQzkxsUQUcLq2gc4dLIyiNNou9DvGhnJzPDHd4VAMCLcTJbC7UMUXrkaDTK+rqzQTEmkt5fh1a7ETum9rxBpFKLzbHIQpZH/CNnIcsPZUdCPk4JURyFePpjtyaDdilCzoUPIQ0UnvNpfv/6aX7Phfu1ML/m/nOrvjt5aQhTAQAA","/uv/uv.handler.js":"","/uv/uv.sw.js":""};
const store = new Map(Object.entries(ASSETS).map(([k, v]) => [k, Buffer.from(v, 'base64')]));
const bare = createBareServer('/bare/');
function serve(req, res) {
  let p = decodeURIComponent(req.url.split('?')[0]);
  if (p === '/healthz') { res.writeHead(200); return res.end('ok'); }
  if (p === '/') p = '/index.html';
  const gz = store.get(p);
  if (!gz) { res.writeHead(404, { 'content-type': 'text/plain' }); return res.end('not found'); }
  const h = { 'content-type': MIME[p.split('.').pop()] || 'application/octet-stream',
    'cache-control': p === '/sw.js' ? 'no-cache' : 'public, max-age=3600', 'vary': 'accept-encoding' };
  if (/\bgzip\b/.test(req.headers['accept-encoding'] || '')) { h['content-encoding'] = 'gzip'; res.writeHead(200, h); res.end(gz); }
  else { res.writeHead(200, h); res.end(zlib.gunzipSync(gz)); }
}
const server = http.createServer((req, res) => (bare.shouldRoute(req) ? bare.routeRequest(req, res) : serve(req, res)));
server.on('upgrade', (req, socket, head) => (bare.shouldRoute(req) ? bare.routeUpgrade(req, socket, head) : socket.end()));
server.listen(PORT, '0.0.0.0', () => console.log('Yoroxy LowBand: http://localhost:' + PORT));
